-- '등록/복학/휴학/재입학' 태그를 되살린다. V25 가 '학부'·'대학원'으로 흡수했는데 학부 행정실이
-- 태그 유지를 요청했다(2026-09-17). 연결 목록은 V25 직전 백업(2026-09-14 00:00)의 196건이다.
-- V25 가 얹어 준 '학부'·'대학원'은 그대로 둔다 — 걷어내면 151건이 다시 어느 레벨 필터에도 안 잡힌다.

-- ENUM 은 끝에 붙인다 — 중간에 끼우면 기존 값의 내부 인덱스가 밀린다.
ALTER TABLE tag_in_notice
    MODIFY COLUMN name ENUM (
        'SCHOLARSHIP', 'UNDERGRADUATE', 'GRADUATE', 'MINOR',
        'ADMISSIONS', 'GRADUATIONS', 'RECRUIT', 'STUDENT_EXCHANGE',
        'INNER_EVENTS_PROGRAMS', 'OUTER_EVENTS_PROGRAMS', 'INTERNATIONAL',
        'CONTESTS', 'CAMPUS_LIFE', 'REGISTRATIONS'
        ) NULL;

INSERT INTO tag_in_notice (name, created_at, modified_at)
VALUES ('REGISTRATIONS', NOW(6), NOW(6));

-- 로컬·staging 처럼 해당 공지가 없는 DB 에서는 JOIN 이 비어 연결만 건너뛴다.
